// (docblock: why — the outage question "can legs start on this SHA", the
// closed reason set, best-effort status, exactly-once, dryRun suppressed)

/** Remember that this leg emitted its leg-start line (exactly-once guard). */
function markLegStartEmitted(line) {
   _legStartEmitted = true;
   _legStartLine = line;
   return line;
}

function currentLegStartLine() {
   return _legStartLine;
}

/** The head SHA the leg ran against: the pre-flight head, else a fresh rev-parse; null when neither resolves. */
function resolveLegStartHeadSha() {
   var remembered = currentPreflightHeadSha();
   if (remembered && /^[0-9a-f]{7,40}$/i.test(remembered)) return remembered;
   try {
       var sha = cleanCommandOutput(runCmd({ command: 'git rev-parse HEAD' }) || '').trim();
       if (/^[0-9a-f]{7,40}$/i.test(sha)) return sha;
   } catch (e) {
       console.warn('leg-start: head SHA not resolvable (commit status skipped):', e && e.message ? e.message : e);
   }
   return null;
}

/** Best-effort commit status for the leg-start signal — a posting failure never fails the leg. */
function postLegStartStatusBestEffort(config, customParams, body) {
   try {
       if (!config) {
           console.warn('leg-start commit status skipped: no config (line stays log-only)');
           return null;
       }
       var tracker = trackersModule.createTracker(config, customParams || {});
       if (tracker.provider() !== 'github') return null;
       if (!(config.repository && config.repository.owner && config.repository.repo)) {
           console.warn('leg-start commit status skipped: no repository scope in config');
           return null;
       }
       var sha = resolveLegStartHeadSha();
       if (!sha) return null;
       var args = legStartSignal.buildCommitStatusArgs({
           workspace: config.repository.owner,
           repository: config.repository.repo,
           sha: sha,
           ok: body.ok === true,
           branchName: body.branchName,
           reasonClass: body.reasonClass,
           runUrl: legFailureReport.runUrlFromEnv(readEnvVar)
       });
       github_create_commit_status(args);
       console.log('Posted commit status ' + args.context + ' on ' + sha.substring(0, 8) +
           (args.targetUrl ? ' → ' + args.targetUrl : '));
       return args;
   } catch (e) {
       console.warn('leg-start commit status posting failed (non-fatal):', e);
       return null;
   }

/**
 * The ok half of the signal: setup crossed, the dev branch is ready.
 * `ticket` is the resolved ticket (branch-name resolution input).
 */
function emitLegStartOk(config, customParams, ticket, branchName) {
   if (_legStartEmitted) return null;
   var line = legStartSignal.okSummaryLine(branchName);
   markLegStartEmitted(line);
   console.log(line);
   postLegStartStatusBestEffort(config, customParams, { ok: true, branchName: branchName });
   return line;
}

/** The failed half: classify the setup error, log the line, post the status. */
function emitLegStartFailed(config, customParams, errorText) {
   if (_legStartEmitted) return null;
   var reasonClass = legStartSignal.classifySetupError(errorText);
   var line = legStartSignal.failedSummaryLine(reasonClass, errorText);
   markLegStartEmitted(line);
   console.log(line);
   postLegStartStatusBestEffort(config, customParams, { ok: false, reasonClass: reasonClass });
   return line;
}
``

